    module fp_types =

        /// <summary>
        /// The type of a function that can be converted to FP.
        /// </summary>
        type FPFnInput =
            delegate of [<ParamArray>] args: obj [] -> unit

        [<RequireQualifiedAccess>]
        type FPArity =
            | ``1`` = 1
            | ``2`` = 2
            | ``3`` = 3
            | ``4`` = 4

        /// <summary>
        /// FP function interface. It infers the arity of the function and returns the
        /// corresponding FP function interface.
        /// </summary>
        [<AllowNullLiteral>]
        [<Interface>]
        type FPFn<'Fn, 'Arity> =
            interface end

        /// <summary>
        /// FP function interface with 1 arguments.
        /// </summary>
        [<AllowNullLiteral>]
        [<Interface>]
        type FPFn1<'Result, 'Arg> =
            [<Emit("$0($1...)")>]
            abstract member Invoke: unit -> DateFns.fp_types.FPFn1<'Result, 'Arg>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg: 'Arg -> 'Result

        /// <summary>
        /// FP function interface with 2 arguments.
        /// </summary>
        [<AllowNullLiteral>]
        [<Interface>]
        type FPFn2<'Result, 'Arg2, 'Arg1> =
            [<Emit("$0($1...)")>]
            abstract member Invoke: unit -> DateFns.fp_types.FPFn2<'Result, 'Arg2, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg2: 'Arg2 -> DateFns.fp_types.FPFn1<'Result, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg2: 'Arg2 * arg1: 'Arg1 -> 'Result

        /// <summary>
        /// FP function interface with 3 arguments.
        /// </summary>
        [<AllowNullLiteral>]
        [<Interface>]
        type FPFn3<'Result, 'Arg3, 'Arg2, 'Arg1> =
            [<Emit("$0($1...)")>]
            abstract member Invoke: unit -> DateFns.fp_types.FPFn3<'Result, 'Arg3, 'Arg2, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg3: 'Arg3 -> DateFns.fp_types.FPFn2<'Result, 'Arg2, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg3: 'Arg3 * arg2: 'Arg2 -> DateFns.fp_types.FPFn1<'Result, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg3: 'Arg3 * arg2: 'Arg2 * arg1: 'Arg1 -> 'Result

        /// <summary>
        /// FP function interface with 4 arguments.
        /// </summary>
        [<AllowNullLiteral>]
        [<Interface>]
        type FPFn4<'Result, 'Arg4, 'Arg3, 'Arg2, 'Arg1> =
            [<Emit("$0($1...)")>]
            abstract member Invoke: unit -> DateFns.fp_types.FPFn4<'Result, 'Arg4, 'Arg3, 'Arg2, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg4: 'Arg4 -> DateFns.fp_types.FPFn3<'Result, 'Arg3, 'Arg2, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg4: 'Arg4 * arg3: 'Arg3 -> DateFns.fp_types.FPFn2<'Result, 'Arg2, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg4: 'Arg4 * arg3: 'Arg3 * arg2: 'Arg2 -> DateFns.fp_types.FPFn1<'Result, 'Arg1>
            [<Emit("$0($1...)")>]
            abstract member Invoke: arg4: 'Arg4 * arg3: 'Arg3 * arg2: 'Arg2 * arg1: 'Arg1 -> 'Result

